import React from 'react';
import './Header.css';

function Header({
  mode,
  aiActive,
  activePhase,
  connected,
  onModeChange,
  onStartAI,
  onStopAI,
  decisionExplanation
}) {
  return (
    <header className="header">
      <div className="header-left">
        <h1 className="header-title">Input-Adaptive Traffic Control</h1>
        <span className={`connection-badge ${connected ? 'connected' : 'disconnected'}`}>
          <span className="connection-dot" />
          {connected ? 'Connected' : 'Disconnected'}
        </span>
      </div>

      <div className="header-center">
        <div className="mode-info">
          <span className="active-phase-label">
            Active Phase: <strong>{activePhase === 'north-south' ? 'N/S' : 'E/W'}</strong>
          </span>
          {decisionExplanation && (
            <span className="decision-explanation" title={decisionExplanation}>
              {decisionExplanation.length > 60
                ? decisionExplanation.substring(0, 57) + '...'
                : decisionExplanation}
            </span>
          )}
        </div>
      </div>

      <div className="header-right">
        <div className="mode-controls">
          <div className="mode-selector">
            <button
              className={`mode-btn ${mode === 'AI' ? 'active ai-mode' : ''}`}
              onClick={() => onModeChange('AI')}
              title="AI adaptive control"
            >
              AI Mode
            </button>
            <button
              className={`mode-btn ${mode === 'MANUAL' ? 'active manual-mode' : ''}`}
              onClick={() => onModeChange('MANUAL')}
              title="Manual operator control"
            >
              Manual
            </button>
            <button
              className={`mode-btn ${mode === 'FAULT' ? 'active fault-mode' : ''}`}
              onClick={() => onModeChange('FAULT')}
              title="Fault safe state"
            >
              Fault
            </button>
          </div>

          {mode === 'AI' && (
            <div className="ai-controls">
              {aiActive ? (
                <button className="ai-btn stop-btn" onClick={onStopAI}>
                  Stop AI
                </button>
              ) : (
                <button className="ai-btn start-btn" onClick={onStartAI}>
                  Start AI
                </button>
              )}
            </div>
          )}
        </div>

        <div className="status-indicators">
          <span className={`status-badge mode-badge-${mode.toLowerCase()}`}>
            {mode}
          </span>
          {mode === 'AI' && (
            <span className={`status-badge ${aiActive ? 'ai-active' : 'ai-inactive'}`}>
              {aiActive ? 'AI Active' : 'AI Paused'}
            </span>
          )}
          <span className="simulation-badge">
            Simulation Mode
          </span>
        </div>
      </div>
    </header>
  );
}

export default Header;
